// Mỗi ảnh 1 item (nhóm cu/moi, vị trí); bỏ hậu tố #fb #zalo #tay #src=
const p = $('Khi được gọi').first().json;
const sach = (u) => String(u || '').trim().replace(/#(fb|zalo|tay|src=[a-z0-9]+)$/i, '');
const out = [];
(p.cu || []).forEach((u, i) => { if (sach(u)) out.push({ json: { nhom: 'cu', vt: i, url: sach(u) } }); });
(p.moi || []).forEach((u, i) => { if (sach(u)) out.push({ json: { nhom: 'moi', vt: i, url: sach(u) } }); });
return out.length ? out : [{ json: { nhom: 'rong', vt: 0, url: '' } }];

// Đọc BMP 17x16 -> độ sáng -> dHash 256 bit; ảnh mới trùng ảnh cũ / ảnh mới trước đó nếu khác <= 20 bit và cùng tỉ lệ
const ds = $('Danh sách ảnh').all().map(i => i.json);
const it = $input.all();
function xam(b) {
  if (b.toString('ascii', 0, 2) !== 'BM') return null;
  const off = b.readUInt32LE(10), w = b.readInt32LE(18), hRaw = b.readInt32LE(22), bpp = b.readUInt16LE(28);
  const h = Math.abs(hRaw), Bp = bpp / 8, row = Math.ceil(w * Bp / 4) * 4;
  if (w !== 17 || h !== 16 || Bp < 3) return null;
  const g = [];
  for (let y = 0; y < h; y++) { const ry = hRaw > 0 ? h - 1 - y : y;
    for (let x = 0; x < w; x++) { const o = off + ry * row + x * Bp; g.push(0.114 * b[o] + 0.587 * b[o + 1] + 0.299 * b[o + 2]); } }
  return g;
}
const H = [];
for (let i = 0; i < it.length; i++) {
  let g = null; try { g = xam(await this.helpers.getBinaryDataBuffer(i, 'data')); } catch (e) {}
  H.push(g ? Array.from({ length: 256 }, (_, k) => { const y = Math.floor(k / 16), x = k % 16; return g[y * 17 + x] > g[y * 17 + x + 1] ? 1 : 0; }) : null);
}
const kc = (a, b) => a.reduce((s, v, k) => s + (v !== b[k] ? 1 : 0), 0);
const trung = []; let loi = 0;
ds.forEach((d, i) => {
  if (d.nhom !== 'moi') return;
  if (!H[i]) { loi++; return; }
  for (let j = 0; j < i; j++) {
    if (!H[j] || ds[j].nhom === 'rong') continue;
    if (ds[j].nhom === 'moi' && trung.some(t => t.moi === ds[j].vt)) continue;
    const d2 = kc(H[i], H[j]);
    if (d2 <= 20) { trung.push({ moi: d.vt, nhom: ds[j].nhom, vt: ds[j].vt, kc: d2 }); break; }
  }
});
return [{ json: { trung, loi, soAnh: ds.length } }];
